            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x7BF1560ACD39F444ULL) ^ aOUSaltE[(((511U - aIndex) + 337U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x3D19A18640B66C7BULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0xAD89DD0D0EDFAB7BULL;
