            aOrbiterD = RotL64((aOrbiterD * 0x728B5FD38DA0E701ULL), 43U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterG) + 0x0821763A36D5BECDULL) + aOUSaltD[((aIndex + 278U)) & S_SALT1];
