            aOrbiterK = RotL64((aOrbiterK * 0x2B776070D09160A3ULL), 23U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x0E6CF273AA4A6B3FULL) + aOUSaltF[(((511U - aIndex) + 213U)) & S_SALT1];
