            aOrbiterC = (((aWandererB + RotL64(aPrevious, 27U)) + RotL64(aCarry, 27U)) + 0xC58AAACA40D56D0AULL) + aOASaltF[((aIndex + 98U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aScatter, 13U)) + 0x513E6E72EE06B660ULL;
            aOrbiterF = (aWandererK + RotL64(aIngress, 23U)) + 0x1DE1EF9583DF1568ULL;
