            aIngress = TwistMix64::DiffuseA((aIngress ^ aTwistDomainWordIngress));
            //
            aCross = (RotL64(aWoodLaneA[((S_BLOCK1 - aIndex + 7701U)) & S_BLOCK1], 48U) ^ RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 7617U)) & S_BLOCK1], 13U));
            aCross ^= RotL64(aKeyRowReadB[((aIndex + 6300U)) & W_KEY1], 39U);
            aCross = TwistMix64::DiffuseA((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 53U) + RotL64(aCross, 41U)) ^ (RotL64(aIngress, 24U) ^ RotL64(aCarry, 5U));
