            aScatter = (RotL64(aIngress, 58U) + RotL64(aCross, 43U)) ^ (RotL64(aPrevious, 11U) ^ RotL64(aCarry, 23U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterD = ((aWandererC + RotL64(aCross, 58U)) + RotL64(aCarry, 39U)) + 0x5990194285FBF8E9ULL;
            aOrbiterB = ((aWandererI + RotL64(aPrevious, 23U)) + RotL64(aCarry, 27U)) + 0x7BE66C24194249D7ULL;
            aOrbiterA = ((aWandererK + RotL64(aScatter, 29U)) + 0xB132A688A844BCBBULL) + aOASaltE[((aIndex + 39U)) & S_SALT1];
            aOrbiterH = (((aWandererD + RotL64(aIngress, 11U)) + RotL64(aCarry, 53U)) + 0x3329C82744FB5B33ULL) + aOASaltF[((aIndex + 257U)) & S_SALT1];
            aOrbiterF = (aWandererE + RotL64(aCross, 35U)) + 0x51870C9BF59492F7ULL;
            aOrbiterC = ((aWandererF + RotL64(aScatter, 41U)) + 0x4E1BE213B9032C45ULL) + aOASaltA[(((511U - aIndex) + 14U)) & S_SALT1];
            aOrbiterE = (aWandererJ + RotL64(aIngress, 51U)) + 0xAF65EF254AC42826ULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x8F8911C7CBACFA06ULL) + aOUSaltC[(((511U - aIndex) + 34U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0xF04E4FD5A7BB0767ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xAC26DF515DDC8CC3ULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0xAF4A1D9591D41B7CULL;
