            aOrbiterB = RotL64((aOrbiterB * 0xD0F8ADC9C5C0F20DULL), 29U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0x9B7077DDC602AB3CULL) + aOUSaltE[(((511U - aIndex) + 435U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0xE1BDD7B8B528A5ECULL;
            aOrbiterC = RotL64((aOrbiterC * 0xD4F2B70B41554945ULL), 41U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterC) + 0x4F72830C8D690B87ULL) + aOUSaltA[((aIndex + 405U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xF949E6B60DC04620ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1E3E2B3C5BCE9861ULL), 13U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x53308E9DCC24ADB1ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xCA9B5AF28F683D55ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xE3B62BBF994B4263ULL), 35U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterA, 41U);
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterD, 11U));
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterH, 52U));
            aIngress = aIngress + RotL64(aOrbiterC, 5U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererI = aWandererI ^ ((RotL64(aCross, 23U) + aOrbiterF) + RotL64(aOrbiterE, 37U));
            aWandererD = aWandererD + ((((RotL64(aScatter, 5U) + RotL64(aOrbiterC, 57U)) + aOrbiterA) + RotL64(aCarry, 47U)) + aWUSaltA[(((511U - aIndex) + 7U)) & S_SALT1]);
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 35U) + aOrbiterB) + RotL64(aOrbiterF, 47U)) + aWUSaltC[((aIndex + 471U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aIngress, 57U) + RotL64(aOrbiterD, 21U)) + aOrbiterC) + aWUSaltF[(((511U - aIndex) + 361U)) & S_SALT1]);
