        // Ingress:
        //      aFuseLaneA (-->), aWindLaneC (-->), aPlasmaLaneA (-->), aMagmaLaneD (<-?->)
        //
        // Cross:
        //      aWindLaneD (<--), aWindLaneB (<--), aCrystalLaneC (<--), aMagmaLaneA (<-?->)
        //
        // Destination:
        //      aFuseLaneB
