            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 9935U)) & S_BLOCK1], 21U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 14896U)) & S_BLOCK1], 43U));
            aCross ^= (RotL64(aCrystalLaneC[((S_BLOCK1 - aIndex + 10330U)) & S_BLOCK1], 5U) ^ RotL64(aMagmaLaneA[((aIndex + 9896U)) & S_BLOCK1], 56U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCarry, 41U) + RotL64(aPrevious, 23U)) ^ (RotL64(aCross, 60U) ^ RotL64(aIngress, 11U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = (aWandererB + RotL64(aIngress, 53U)) + 0x8F5966B030F4DDB4ULL;
            aOrbiterG = (((aWandererA + RotL64(aCross, 13U)) + RotL64(aCarry, 39U)) + 0xEBF1F1C2814A3A2BULL) + aOASaltB[((aIndex + 329U)) & S_SALT1];
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 26U)) + RotL64(aCarry, 23U)) + 0xAEC54DB9260BC51CULL;
            aOrbiterA = (((aWandererH + RotL64(aScatter, 43U)) + RotL64(aCarry, 51U)) + 0x606964CDEF96A4AEULL) + aOASaltC[((aIndex + 444U)) & S_SALT1];
            aOrbiterC = ((aWandererF + RotL64(aIngress, 37U)) + 0x9DA9D6FDA2A8FB24ULL) + aOASaltA[(((511U - aIndex) + 198U)) & S_SALT1];
            aOrbiterJ = ((aWandererJ + RotL64(aScatter, 19U)) + 0xB5F35059AE7C948EULL) + aOASaltH[((aIndex + 456U)) & S_SALT1];
            aOrbiterB = (aWandererE + RotL64(aPrevious, 3U)) + 0x2DA2D878FEB75059ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x69B9CC4702E9658EULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x4C366815A44ABF77ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF675CFCA72CBAF73ULL), 3U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterC) + 0x2F31F58D2812C828ULL) + aOUSaltH[(((511U - aIndex) + 301U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x3D8FBC793B08D415ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xABA31CC6D3B92613ULL), 13U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x730D7E9E9407928CULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x9E2374A7C9DA70E8ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xCA6CEE6FED34825DULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xB7D1B1E4C2B8618BULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0x7AA77EB695EC733AULL) ^ aOUSaltE[(((511U - aIndex) + 458U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x40AD49EB13BB187FULL), 37U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0xE441127109B9968DULL) + aOUSaltG[(((511U - aIndex) + 75U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x5A5EB9E7CE938CB7ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xCABB4B9D10DDFBCFULL), 51U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0xBED95A626A47502DULL) + aOUSaltB[(((511U - aIndex) + 345U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x5A588822B2BEF0F1ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x486FE265E11DDA3BULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x301EAC0B2916D5ECULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0xB2E86F1D133D9726ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x9187E556206FCFEBULL), 21U);
            //
            aIngress = RotL64(aOrbiterC, 47U) ^ aOrbiterA;
            aIngress = aIngress + (RotL64(aOrbiterB, 53U) ^ aOrbiterG);
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterF, 29U));
            aIngress = aIngress + RotL64(aOrbiterK, 23U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererH = aWandererH ^ (((RotL64(aIngress, 5U) + RotL64(aOrbiterJ, 5U)) + aOrbiterG) + aWUSaltH[((aIndex + 117U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aScatter, 58U) + aOrbiterA) + RotL64(aOrbiterJ, 13U)) + RotL64(aCarry, 37U));
            aWandererF = aWandererF ^ (((RotL64(aCross, 37U) + RotL64(aOrbiterK, 57U)) + aOrbiterA) + aWUSaltA[(((511U - aIndex) + 361U)) & S_SALT1]);
            aWandererG = aWandererG + ((((RotL64(aPrevious, 29U) + aOrbiterC) + RotL64(aOrbiterK, 29U)) + RotL64(aCarry, 51U)) + aWUSaltE[((aIndex + 139U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aCross, 11U) + RotL64(aOrbiterC, 19U)) + aOrbiterF);
            aWandererA = aWandererA + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterK, 39U)) + aOrbiterF) + aWUSaltF[(((511U - aIndex) + 504U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 21U) + aOrbiterB) + RotL64(aOrbiterA, 48U));
