            aIngress ^= (RotL64(aFireLaneB[((aIndex + 20999U)) & S_BLOCK1], 19U) ^ RotL64(aCrystalLaneB[((aIndex + 17839U)) & S_BLOCK1], 27U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateBDomainWordIngress));
            //
            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 19008U)) & S_BLOCK1], 51U) ^ RotL64(aVaporLaneB[((S_BLOCK1 - aIndex + 17907U)) & S_BLOCK1], 43U));
            aCross ^= (RotL64(aAetherLaneC[((S_BLOCK1 - aIndex + 19642U)) & S_BLOCK1], 10U) ^ RotL64(aKineticLaneD[((aIndex + 24424U)) & S_BLOCK1], 29U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateBDomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 21U) + RotL64(aCross, 57U)) ^ (RotL64(aCarry, 41U) + RotL64(aIngress, 6U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterJ = (aWandererH + RotL64(aIngress, 43U)) + 0x63CD3A91EF8EF3C9ULL;
            aOrbiterK = (((aWandererI + RotL64(aCross, 51U)) + RotL64(aCarry, 37U)) + 0x3306C71B6176BACDULL) + aOASaltA[((aIndex + 156U)) & S_SALT1];
            aOrbiterC = ((aWandererC + RotL64(aPrevious, 35U)) + RotL64(aCarry, 21U)) + 0x8869D63F02FE5AD5ULL;
            aOrbiterF = (((aWandererD + RotL64(aScatter, 57U)) + RotL64(aCarry, 53U)) + 0xCEF45C9BB35FC5B2ULL) + aOASaltH[(((511U - aIndex) + 103U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aIngress, 22U)) + 0x6F03F1426CBD235FULL;
            aOrbiterI = (aWandererE + RotL64(aScatter, 13U)) + 0xD2074E9E6A7965F0ULL;
            aOrbiterE = ((aWandererK + RotL64(aPrevious, 3U)) + 0x2A2382B6903EF058ULL) + aOASaltC[((aIndex + 186U)) & S_SALT1];
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0x85049AFCBAC7DF51ULL) + aOUSaltA[(((511U - aIndex) + 52U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x836B508B361748E7ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xFDA198FE88AA4F8DULL), 47U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterH) + 0xA0F7A22AB6091F13ULL) + aOUSaltF[(((511U - aIndex) + 317U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0x108CB6C747987EE8ULL) ^ aOUSaltH[(((511U - aIndex) + 389U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x1834910A2989668DULL), 41U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0x9BD6D62C0A0AEE9BULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0xFD836DA9442E341AULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x2AF84B5E503ADD85ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x19020C9B94183A74ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xD7509DAC0CD967EBULL) ^ aOUSaltB[(((511U - aIndex) + 17U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x0C1F514C045E5339ULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xCD89DF94A05A75CEULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0x5ECF55F0EA14D3DBULL) ^ aOUSaltE[(((511U - aIndex) + 73U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xE59849A81BFAA3F5ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x39AEC6C88894D012ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xCEE233808A04211BULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC176EC7BE490440BULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x4DBF6EDE7A13A2CFULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0xCE051E242ED918E3ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x0E6055C936D7B179ULL), 23U);
            //
            aIngress = RotL64(aOrbiterC, 19U) ^ aOrbiterH;
            aIngress = aIngress + (RotL64(aOrbiterK, 5U) ^ aOrbiterJ);
            aIngress = aIngress + (RotL64(aOrbiterE, 35U) ^ aOrbiterI);
            aIngress = aIngress + RotL64(aOrbiterF, 53U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererH = aWandererH ^ (((RotL64(aIngress, 18U) + aOrbiterH) + RotL64(aOrbiterC, 41U)) + aWUSaltA[((aIndex + 291U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aPrevious, 11U) + RotL64(aOrbiterE, 35U)) + aOrbiterH) + RotL64(aCarry, 29U));
