            aWandererC = aWandererC ^ ((RotL64(aCross, 53U) + aOrbiterE) + RotL64(aOrbiterJ, 53U));
            aWandererE = aWandererE + (((RotL64(aScatter, 41U) + RotL64(aOrbiterH, 13U)) + aOrbiterF) + aWUSaltC[((aIndex + 160U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 29U) + aOrbiterK) + RotL64(aOrbiterF, 5U));
