            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterH, 29U);
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterD, 13U));
            aIngress = aIngress + (RotL64(aOrbiterJ, 60U) ^ aOrbiterF);
            aIngress = aIngress + RotL64(aOrbiterI, 41U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererH = aWandererH ^ (((RotL64(aIngress, 37U) + aOrbiterB) + RotL64(aOrbiterF, 35U)) + aWUSaltF[((aIndex + 406U)) & S_SALT1]);
            aWandererJ = aWandererJ + (((RotL64(aCross, 27U) + aOrbiterH) + RotL64(aOrbiterD, 44U)) + RotL64(aCarry, 5U));
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterA, 5U)) + aOrbiterD);
            aWandererA = aWandererA + ((((RotL64(aScatter, 43U) + RotL64(aOrbiterD, 57U)) + aOrbiterJ) + RotL64(aCarry, 53U)) + aWUSaltD[(((511U - aIndex) + 303U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aCross, 5U) + RotL64(aOrbiterB, 51U)) + aOrbiterI);
            aWandererK = aWandererK + (((RotL64(aPrevious, 21U) + aOrbiterA) + RotL64(aOrbiterB, 21U)) + aWUSaltA[((aIndex + 163U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aScatter, 14U) + aOrbiterD) + RotL64(aOrbiterB, 29U));
            //
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererF, 57U));
